<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/_auth.php';$p=portal_require();$st=db()->prepare("SELECT a.starts_at,a.status,a.modality,a.meeting_url,u.name professional_name FROM appointments a JOIN users u ON u.id=a.professional_id AND u.tenant_id=a.tenant_id WHERE a.tenant_id=:t AND a.patient_id=:p AND a.starts_at>=NOW() AND a.status NOT IN ('cancelled','completed') ORDER BY a.starts_at LIMIT 8");$st->execute(['t'=>$p['tenant_id'],'p'=>$p['id']]);$appointments=$st->fetchAll();$st=db()->prepare("SELECT * FROM therapeutic_tasks WHERE tenant_id=:t AND patient_id=:p AND status='open' ORDER BY due_date IS NULL,due_date LIMIT 12");$st->execute(['t'=>$p['tenant_id'],'p'=>$p['id']]);$tasks=$st->fetchAll();$st=db()->prepare("SELECT * FROM mood_logs WHERE tenant_id=:t AND patient_id=:p ORDER BY created_at DESC LIMIT 1");$st->execute(['t'=>$p['tenant_id'],'p'=>$p['id']]);$last=$st->fetch();layout('Meu portal',function()use($p,$appointments,$tasks,$last){?><div class="page-head"><div><span class="eyebrow"><?=e($p['tenant_name'])?></span><h1>Olá, <?=e($p['preferred_name']?:explode(' ',$p['name'])[0])?></h1><p>Este espaço mostra somente informações compartilhadas com você.</p></div><a class="button" href="<?=e(url('portal/diario.php'))?>">Registrar humor</a></div><div class="kpi-grid"><div class="kpi"><small>Próximas consultas</small><strong><?=count($appointments)?></strong></div><div class="kpi"><small>Tarefas abertas</small><strong><?=count($tasks)?></strong></div><div class="kpi"><small>Último humor</small><strong><?= $last?e($last['mood_score']).'/10':'—'?></strong></div></div><div class="grid-2"><section class="card"><h2>Próximas consultas</h2><div class="stack"><?php if(!$appointments):?><p class="muted">Nenhuma consulta futura.</p><?php endif?><?php foreach($appointments as $a):?><article class="record"><strong><?=e(date('d/m/Y \à\s H:i',strtotime($a['starts_at'])))?></strong><p><?=e($a['professional_name'])?> · <?=e($a['modality']==='online'?'On-line':'Presencial')?> · <span class="status <?=e($a['status'])?>"><?=e($a['status'])?></span></p><?php if($a['meeting_url']&&$a['modality']==='online'):?><a href="<?=e($a['meeting_url'])?>" target="_blank" rel="noopener">Entrar na sala on-line</a><?php endif?></article><?php endforeach?></div></section><section class="card"><h2>Tarefas terapêuticas</h2><div class="stack"><?php if(!$tasks):?><p class="muted">Nenhuma tarefa pendente.</p><?php endif?><?php foreach($tasks as $t):?><article class="task"><div><strong><?=e($t['title'])?></strong><p><?=nl2br(e($t['instructions']??''))?></p><?php if($t['due_date']):?><small class="muted">Prazo: <?=e(date('d/m/Y',strtotime($t['due_date'])))?></small><?php endif?><form method="post" action="<?=e(url('portal/task.php'))?>" style="margin-top:8px"><?=csrf_field()?><input type="hidden" name="id" value="<?=$t['id']?>"><button class="button ghost small">Marcar como concluída</button></form></div></article><?php endforeach?></div></section></div><?php },['portal'=>true]);
